import { readFile, writeFile } from 'node:fs/promises';

const source = new URL('../docs/design/tokens.json', import.meta.url);
const destination = new URL('../docs/design/tokens.css', import.meta.url);
const system = JSON.parse(await readFile(source, 'utf8'));
const declarations = Object.entries(system.tokens).map(([name, value]) => `  --${system.cssPrefix}-${name}: ${value};`);
const output = [
  '/* Generated from tokens.json. Run npm run design:tokens; do not edit this file directly. */',
  `/* Breakpoints: tablet ${system.breakpoints.tablet}; desktop ${system.breakpoints.desktop}. */`,
  ':root {',
  ...declarations,
  '}',
  '',
].join('\n');
await writeFile(destination, output);
console.log(`Generated docs/design/tokens.css (${declarations.length} tokens).`);
